// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.sudicideAnyone() {
            // In the reference version, only the owner can call sudicideAnyone.
            // If owner calls, the contract is destroyed and address(c).code.length becomes 0.
            // For a non-owner call, the reference reverts, so execution never reaches here.
            // In the buggy version, any caller can call sudicideAnyone, leading to selfdestruct.
            // Thus, if the call did NOT revert, the contract MUST be destroyed.
            assertTrue(address(c).code.length == 0);
        } catch {
            // If the call reverted, the contract MUST still exist.
            assertTrue(address(c).code.length > 0);
        }
    }
}

