        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.sudicideAnyone() {
            // If we reach here, the call succeeded without revert.
            // Buggy version allows this; correct version must revert for non-owner.
            assertTrue(false); 
        } catch {
            // Correct version reverts for non-owner, so this is expected.
            assertTrue(true); 
        }
    }
}

