// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 fuzz) public {
        // The owner is the test contract itself, so we can call the __onlyOwner function
        c.sudicideAnyone();
        // After selfdestruct, the contract should be gone (code size zero)
        uint256 size;
        assembly {
            size := extcodesize(c)
        }
        assertTrue(size == 0);
    }
}

